package org.jfree.data.xy;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.List;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.data.general.Series;
import org.jfree.data.general.SeriesChangeEvent;
import org.jfree.data.general.SeriesException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class XYSeries_addOrUpdate_TriageGen0Test {

    @Test(expected = IllegalArgumentException.class)
    public void testAddOrUpdate_NullX_ThrowsException() {
        XYSeries series = new XYSeries("Test");
        series.addOrUpdate(null, 1.0);
    }

    @Test
    public void testAddOrUpdate_AddNew_NoAutoSort() {
        XYSeries series = new XYSeries("Test", false);
        XYDataItem item = series.addOrUpdate(1.0, 10.0);

        assertNull("Should return null when adding new item", item);
        assertEquals(1, series.getItemCount());
        assertEquals(1.0, series.getX(0).doubleValue(), 0.001);
        assertEquals(10.0, series.getY(0).doubleValue(), 0.001);
    }

    @Test
    public void testAddOrUpdate_AddNew_WithAutoSort() {
        // autoSort = true
        XYSeries series = new XYSeries("Test", true);
        series.addOrUpdate(2.0, 20.0);
        series.addOrUpdate(1.0, 10.0); // Should be inserted at index 0 due to autoSort

        assertEquals(2, series.getItemCount());
        assertEquals(1.0, series.getX(0).doubleValue(), 0.001);
        assertEquals(2.0, series.getX(1).doubleValue(), 0.001);
    }

    @Test
    public void testAddOrUpdate_UpdateExisting_NoDuplicatesAllowed() {
        // allowDuplicateXValues = false
        XYSeries series = new XYSeries("Test", true, false);
        series.addOrUpdate(1.0, 10.0);

        XYDataItem overwritten = series.addOrUpdate(1.0, 20.0);

        assertNotNull("Should return the overwritten item", overwritten);
        assertEquals(10.0, overwritten.getY().doubleValue(), 0.001);
        assertEquals(1, series.getItemCount());
        assertEquals(20.0, series.getY(0).doubleValue(), 0.001);
    }

    @Test
    public void testAddOrUpdate_AddDuplicate_DuplicatesAllowed() {
        // allowDuplicateXValues = true
        XYSeries series = new XYSeries("Test", true, true);
        series.addOrUpdate(1.0, 10.0);
        XYDataItem overwritten = series.addOrUpdate(1.0, 20.0);

        assertNull("Should return null when duplicates are allowed", overwritten);
        assertEquals(2, series.getItemCount());
        assertEquals(1.0, series.getX(0).doubleValue(), 0.001);
        assertEquals(1.0, series.getX(1).doubleValue(), 0.001);
    }

    @Test
    public void testAddOrUpdate_ExceedsMaximumItemCount() {
        XYSeries series = new XYSeries("Test");
        series.setMaximumItemCount(2);

        series.addOrUpdate(1.0, 10.0);
        series.addOrUpdate(2.0, 20.0);
        series.addOrUpdate(3.0, 30.0); // This should trigger removal of index 0

        assertEquals(2, series.getItemCount());
        // Since autoSort is false by default, it appends. 
        // The first item (1.0) should be removed.
        assertEquals(2.0, series.getX(0).doubleValue(), 0.001);
        assertEquals(3.0, series.getX(1).doubleValue(), 0.001);
    }

    @Test
    public void testAddOrUpdate_AutoSortInsertionIndex() {
        // Testing the logic: this.data.add(-index - 1, new XYDataItem(x, y));
        // If binarySearch returns -2, insertion is at index 1.
        XYSeries series = new XYSeries("Test", true);
        series.addOrUpdate(10.0, 100.0);
        series.addOrUpdate(30.0, 300.0);

        // Inserting 20.0 should go between 10 and 30
        series.addOrUpdate(20.0, 200.0);

        assertEquals(3, series.getItemCount());
        assertEquals(10.0, series.getX(0).doubleValue(), 0.001);
        assertEquals(20.0, series.getX(1).doubleValue(), 0.001);
        assertEquals(30.0, series.getX(2).doubleValue(), 0.001);
    }
}
